package com.openminis.app.ui.chat.md

/** HTML character references: the full HTML5 named set (2,125 names) and numeric forms. */
internal object MdEntities {
    private val table: Map<String, String> by lazy {
        val map = HashMap<String, String>(4096)
        for (line in DATA.split('\n')) {
            val eq = line.indexOf('=')
            if (eq > 0) map[line.substring(0, eq)] = line.substring(eq + 1)
        }
        map
    }

    fun named(name: String): String? = table[name]

    /** Decodes one reference such as `&amp;`, `&#35;` or `&#x22;`; an unknown name is returned as written. */
    fun decode(entity: String): String {
        val body = entity.removePrefix("&").removeSuffix(";")
        if (body.startsWith("#")) {
            val num = if (body.length > 1 && (body[1] == 'x' || body[1] == 'X')) body.substring(2).toIntOrNull(16)
            else body.substring(1).toIntOrNull()
            val cp = if (num == null || num == 0 || num > 0x10FFFF || num in 0xD800..0xDFFF) 0xFFFD else num
            return String(Character.toChars(cp))
        }
        return table[body] ?: entity
    }

